import type {
  IAutoMovieRecoveryAtlasCounts,
  IAutoMovieRecoveryAtlasPrimitiveRange,
  IAutoMovieRecoveryDomainAddress,
} from "../../index";

/**
 * Actual tensor-family ownership and engine realization diagnostics.
 *
 * @evidence contracts/development/common.md#meaningful-documentation Unique saved family identity. Closed graph occurrences generated by this family.
 * @evidence contracts/development/design.md#principled-representation Actual engine causes, independent of finite output.
 * @evidence contracts/development/design.md#minimal-and-owned-surface IAutoMovieRecoveryReconstruction, IAutoMovieRecoveryTensorRealization share IAutoMovieRecoveryTensorReport's canonical records; the referenced quantities retain one declaration owner.
 * @evidence contracts/development/design.md#prohibited-design-shortcuts Actual engine numerical populations and error bound.
 */

export interface IAutoMovieRecoveryTensorReport {
  /** Unique saved family identity. */
  id: string;

  /** Closed graph occurrences generated by this family. */
  delegatedGroups: IAutoMovieRecoveryDomainAddress[];

  /** Names of the admitted saved boundary curves. */
  endCurves: string[];

  /** Whether the requested family patch domain was retained. */
  complete: boolean;

  /** Whether retained output met the requested approximation bound. */
  approximationQualified: boolean;

  /** Actual engine numerical populations and error bound. */
  counts: IAutoMovieRecoveryAtlasCounts;

  /** Retained triangles and generating patch intervals. */
  primitiveRanges: IAutoMovieRecoveryAtlasPrimitiveRange[];

  /** Actual engine causes, independent of finite output. */
  diagnostics: string[];
}
